'use client'

import * as React from 'react'
import { Badge } from '@/components/spaceui/badge-squircle'
import { cn } from '@/lib/utils'

export interface SectionHeaderProps {
  title?: string
  description?: string
  link?: string
  badge?: string
  layoutStart?: boolean
  isPage?: boolean
}

export function SectionHeader({ title, description, link, badge, layoutStart, isPage }: SectionHeaderProps) {
  return (
    <div
      className={cn(
        'max-w-2xl flex flex-col items-start justify-start gap-4 mb-12',
        !layoutStart && 'mx-auto items-center justify-center text-center',
      )}
    >
      {badge && (
        <Badge
          size="md"
          className="squircle-2xl/80 md:squircle-3xl/80 px-3 py-1.5 border-none bg-muted text-foreground font-semibold text-base"
        >
          {badge}
        </Badge>
      )}

      {title && (
        <h2
          className={cn(
            layoutStart ? 'text-2xl md:text-3xl font-normal' : 'capitalize text-3xl md:text-4xl font-bold',
            isPage && 'font-normal',
          )}
        >
          {title}
        </h2>
      )}

      {description && (
        <p
          className={cn('text-xl md:text-2xl text-muted-foreground whitespace-pre-line', !layoutStart && 'font-medium')}
        >
          {description}
        </p>
      )}

      {link && (
        <a
          href={link}
          className="inline-flex items-center gap-1 text-xs font-semibold text-muted-foreground hover:text-foreground transition-colors"
        >
          See more &rarr;
        </a>
      )}
    </div>
  )
}

export interface SectionLayoutProps {
  id?: string
  title?: string
  description?: string
  className?: string
  contentClassName?: string
  link?: string
  badge?: string
  children: React.ReactNode
  isFlex?: boolean
  layoutStart?: boolean
  isPage?: boolean
}

export function SectionLayout({
  id,
  title,
  description,
  className,
  contentClassName,
  link,
  badge,
  children,
  isFlex,
  layoutStart,
  isPage,
}: SectionLayoutProps) {
  return (
    <section className={cn('relative w-full py-14 md:py-[104px]', className)} id={id}>
      {(title || badge) && (
        <SectionHeader
          title={title}
          description={description}
          link={link}
          badge={badge}
          layoutStart={layoutStart}
          isPage={isPage}
        />
      )}
      <div
        className={cn(
          'flex flex-col items-center justify-center justify-items-center self-center place-self-center w-full gap-6',
          !isFlex && 'md:grid grid-cols-1 md:grid-cols-2 md:max-w-[90%] place-items-center place-self-center',
          contentClassName,
        )}
      >
        {children}
      </div>
    </section>
  )
}

'use client'

import { motion } from 'motion/react'
import * as React from 'react'
import Image from 'next/image'
import { Frame } from '@/components/ui/frame'
import { Card } from '@/components/ui/card'
import { Badge } from '@/components/spaceui/badge-squircle'
import { resolveEmojiUrl, EmojiSource, EmojiType, EmojiFormat } from '@usespaceui/emoji'
import { cn } from '@/lib/utils'

export interface ReactionsSectionProps {
  reactions?: Record<string, number>
  className?: string
}

const REACTION_CONFIG: Record<
  string,
  {
    char: string
    label: string
  }
> = {
  like: { char: '👍', label: 'Like' },
  heart: { char: '❤️', label: 'Love' },
  celebrate: { char: '🎉', label: 'Celebrate' },
  insightful: { char: '💡', label: 'Insightful' },
  sceptic: { char: '🤔', label: 'Skeptical' },
}

export interface ReactionCardProps {
  char?: string
  label: string
  count: number
  className?: string
}

export function ReactionCard({ char = '👍', label, count, className }: ReactionCardProps) {
  const [isHovered, setIsHovered] = React.useState(false)

  const emojiUrl = React.useMemo(() => {
    if (!char) return ''
    try {
      return resolveEmojiUrl(char, {
        source: EmojiSource.Fluent,
        type: EmojiType.Anim,
        format: EmojiFormat.Webp,
      })
    } catch {
      return ''
    }
  }, [char])

  return (
    <Frame
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
      className={cn('size-full bg-muted squircle-6xl/100 border-0 overflow-hidden p-4', className)}
    >
      <Card className="relative flex flex-col size-full items-center justify-center gap-4 md:gap-8 p-4 squircle-2xl/100 md:squircle-4xl/100 bg-background border-0 overflow-hidden before:hidden shadow-none">
        {emojiUrl && (
          <motion.div
            animate={{
              rotate: isHovered ? -20 : -32,
              scale: isHovered ? 1.15 : 1,
              y: isHovered ? -10 : 0,
            }}
            transition={{ type: 'spring', stiffness: 200, damping: 15 }}
            className="pointer-events-none absolute -bottom-6 -right-6 select-none opacity-15"
          >
            <Image
              src={emojiUrl}
              alt={label}
              width={96}
              height={96}
              unoptimized
              className="size-24 object-contain pointer-events-none select-none"
            />
          </motion.div>
        )}

        <div className="relative w-full flex flex-col gap-2 z-10">
          <div className="relative flex flex-row items-center gap-2 md:gap-4">
            <Badge
              className="capitalize text-xs font-medium size-max bg-muted text-foreground p-2 squircle-2xl/80 md:squircle-3xl/80 border-0 flex items-center justify-center"
              size="sm"
              square
            >
              {emojiUrl ? (
                <Image
                  src={emojiUrl}
                  alt={label}
                  width={32}
                  height={32}
                  unoptimized
                  className="size-8 object-contain pointer-events-none select-none"
                />
              ) : (
                <span className="text-2xl">{char}</span>
              )}
            </Badge>
            <div className="flex flex-col items-start gap-2">
              <h6 className="tracking-wide text-foreground font-medium text-sm md:text-base leading-tight">{label}</h6>
              <p className="text-sm text-muted-foreground leading-[120%] font-medium">{count.toLocaleString()}</p>
            </div>
          </div>
        </div>
      </Card>
    </Frame>
  )
}

export function ReactionsSection({ reactions = {}, className }: ReactionsSectionProps) {
  const items = Object.entries(REACTION_CONFIG).map(([key, config]) => ({
    key,
    char: config.char,
    label: config.label,
    count: reactions[key] || reactions[config.char] || 120,
  }))

  return (
    <div className={cn('grid grid-cols-1 md:grid-cols-3 lg:grid-cols-5 gap-6 w-full', className)}>
      {items.map((item) => (
        <ReactionCard key={item.key} char={item.char} label={item.label} count={item.count} />
      ))}
    </div>
  )
}

'use client'

import { motion } from 'motion/react'
import * as React from 'react'
import { IconSparklesFilled, IconStarFilled, IconBugFilled, IconSettingsFilled } from '@tabler/icons-react'
import { Frame } from '@/components/ui/frame'
import { Card } from '@/components/ui/card'
import { Badge } from '@/components/spaceui/badge-squircle'
import { cn } from '@/lib/utils'
import type { ChangelogItem } from './types'

export interface ChangelogUpdatesCardProps {
  count?: number
  changelog: ChangelogItem[]
  className?: string
}

export function ChangelogUpdatesCard({ count, changelog, className }: ChangelogUpdatesCardProps) {
  const [isHovered, setIsHovered] = React.useState(false)

  const typeIcons = {
    milestone: IconSparklesFilled,
    feature: IconStarFilled,
    fix: IconBugFilled,
    improvement: IconSettingsFilled,
  }

  const typeColors = {
    milestone: 'text-green-500',
    feature: 'text-amber-500',
    fix: 'text-red-500',
    improvement: 'text-blue-500',
  }

  const recentItems = [...changelog].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime()).slice(0, 8)

  const getTopPosition = (index: number) => {
    const basePosition = -5
    const spacing = 42
    return `${basePosition + index * spacing}px`
  }

  return (
    <Frame
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
      className={cn('size-full min-h-54 bg-muted squircle-6xl/100 border-0 overflow-hidden p-4', className)}
    >
      <Card
        className={cn(
          'flex relative flex-col size-full items-center justify-center gap-4 md:gap-8 p-4 squircle-2xl/100 md:squircle-4xl/100 bg-background border-0 overflow-hidden before:hidden shadow-none',
        )}
      >
        <motion.div
          animate={{
            rotate: isHovered ? -20 : -32,
            scale: isHovered ? 1.1 : 1,
            y: isHovered ? -10 : 0,
          }}
          transition={{ type: 'spring', stiffness: 200, damping: 15 }}
          className="pointer-events-none absolute -bottom-6 -right-6 text-[6rem] leading-none opacity-20 select-none"
        >
          ✨
        </motion.div>

        <div className="border-px absolute z-20 left-1/2 top-0 h-full w-2 -translate-x-1/2 transform border-x border-border/10 bg-border/35" />

        <div className="relative flex-1 items-start w-full">
          <motion.div
            animate={{
              y: isHovered ? -120 : 0,
            }}
            transition={{
              type: 'spring',
              stiffness: 60,
              damping: 18,
            }}
            className="absolute left-0 right-0 top-0"
          >
            {recentItems.map((item, index) => {
              const itemType = (item.type || 'feature') as keyof typeof typeIcons
              const Icon = typeIcons[itemType] || IconSparklesFilled

              return (
                <motion.div
                  key={item.id || item.version || index}
                  initial={{ opacity: 0 }}
                  animate={{ opacity: 1 }}
                  transition={{ duration: 0.3, delay: index * 0.05 }}
                  className="absolute"
                  style={{
                    top: getTopPosition(index),
                    ...(index % 2 === 1 ? { left: 'calc(50% + 6px)' } : { right: 'calc(50% + 6px)' }),
                  }}
                >
                  <span
                    className={cn(
                      'absolute top-[14px] h-px w-[8px] bg-border',
                      index % 2 === 1 ? 'left-[-6px]' : 'right-[-6px]',
                    )}
                  />
                  <div className="z-20 inline-block w-[100px] space-y-px squircle-2xl/100 bg-background border-2 border-muted px-2 py-1.5 text-xs overflow-hidden">
                    <div className="flex items-center gap-1">
                      <Badge className="p-[0.075rem] relative" size="sm" square>
                        <Icon className={cn(typeColors[itemType])} size={12} />
                      </Badge>
                      <div className="flex flex-col items-start">
                        <p className="text-sm overflow-hidden text-ellipsis whitespace-nowrap font-semibold text-foreground leading-none">
                          {item.version}
                        </p>
                        <time dateTime={item.date} className="text-[0.5rem] text-muted-foreground leading-none">
                          {new Date(item.date).toLocaleDateString('en-US', {
                            month: 'short',
                            day: 'numeric',
                          })}
                        </time>
                      </div>
                    </div>
                  </div>
                </motion.div>
              )
            })}
          </motion.div>
        </div>

        <div className="pointer-events-none absolute inset-x-0 top-0 z-20 h-16 bg-gradient-to-b from-muted/85 to-transparent" />
        <div className="pointer-events-none absolute inset-x-0 bottom-0 z-20 h-38 bg-gradient-to-t from-muted via-background to-transparent" />

        <div className="relative flex flex-col items-start w-full z-30 mt-auto pointer-events-none">
          <div className="relative flex flex-row items-center gap-2">
            <Badge
              className="capitalize text-xs font-medium bg-[#8e8eff] text-white size-max"
              size="sm"
              square
              variant="default"
            >
              <IconSparklesFilled size={32} />
            </Badge>
            <div className="flex flex-col items-start gap-1">
              <h6 className="tracking-wide text-foreground font-medium">Changelog</h6>
              <p className="flex gap-1 text-xs text-muted-foreground">
                <span className="text-xs text-muted-foreground">{count || changelog.length} updates</span>
              </p>
            </div>
          </div>
        </div>

        <a href="#changelog" className="absolute size-full top-0 left-0 z-30" />
      </Card>
    </Frame>
  )
}
